      "xa012"
    ],
    "selection_reasoning": {
      "xa001": "兵马俑为西安核心世界遗产，推荐必访；室内/展厅比例高，适合不稳定天气，尽管票价未给出但为重点景点。",
      "xa002": "西安城墙为城市地标，可骑行/体验夜景，能提供城市观感与活动（高步行强度需安排在合适时段）。",
      "xa003": "陕西历史博物馆明确免费且主要为室内，适合博物馆爱好者与避暑避雨安排，能节省门票预算。",
      "xa004": "大雁塔文化休闲景区为经典景点，时间可控、交通便利，兼具室内/户外体验。",
      "xa005": "大唐不夜城适合夜间活动与演出、步行街体验，餐饮与夜游结合，补充白天博物馆/遗址的安排。",
      "xa006": "回民街为必访小吃街，低强度，便于安排行程晚餐与小吃体验，且不占用过多预算（主要消费在餐饮）。",
      "xa007": "华清宫为园林与历史结合的景区，推荐作为半日游景点，文化价值高。",
      "xa011": "西安博物院为小雁塔附近的博物馆，部分展区室内，有免费信息，适合文化行程补充。",
      "xa008": "碑林博物馆因与已有博物馆类重合性高且非必选而未优先；可替代但本次未列入主行程。",
      "xa009": "曲江池为户外公园，主题偏休闲且与大雁塔/曲江片区重合，可作为临时替换，但在优先级上落后于世界遗产与必吃街区。",
      "xa010": "骊山景区为强体力登山类，需整日且体力消耗大，不利于三天行程内其他重点景点兼顾，故排除为非优先。",
      "xa012": "大明宫国家遗址公园为大范围户外遗址，访问强度高且与其他遗址主题重复，优先级次于兵马俑与城墙。"
    }
  },
